class Solution {
    public List<Integer> relocateMarbles(int[] nums,int[] moveFrom,int[] moveTo){
        Set<Integer> positions=new HashSet<>();
        for(int value:nums)positions.add(value);
        for(int i=0;i<moveFrom.length;i++){
            positions.remove(moveFrom[i]);
            positions.add(moveTo[i]);
        }
        List<Integer> answer=new ArrayList<>(positions);
        Collections.sort(answer);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun relocateMarbles(nums:IntArray,moveFrom:IntArray,moveTo:IntArray):List<Int>{
        val positions=nums.toMutableSet();
        for(i in moveFrom.indices){
            positions.remove(moveFrom[i]);
            positions.add(moveTo[i])
        };
        return positions.sorted()
    }
}

code.cpp:
class Solution {
    public:vector<int> relocateMarbles(vector<int>& nums,vector<int>& moveFrom,vector<int>& moveTo){
        unordered_set<int> positions(nums.begin(),nums.end());
        for(int i=0;i<(int)moveFrom.size();++i){
            positions.erase(moveFrom[i]);
            positions.insert(moveTo[i]);
        }
        vector<int> answer(positions.begin(),positions.end());
        sort(answer.begin(),answer.end());
        return answer;
    }
};
